// Phase 3 — Timelock batch execution (Arc testnet, chainId 5042002)
// Executes the scheduled P3 oracle-migration batch once the 48h delay has elapsed.
// Run unattended via the p3-execute-batch.service systemd unit.
//
// Batch id: 0x31218725d7f61c128825c982ecd962183136a0b755381d128052a09c84c23587
// Contents: 7 Registry.setOracle + 2 Registry.setDeviation (TRYC/BRLC -> 200 bps).
// The executeBatch calldata below was built and verified locally
// (cast hashOperationBatch matched the on-chain scheduled batch id).

import { createWalletClient, createPublicClient, http, defineChain } from 'viem';
import { privateKeyToAccount } from 'viem/accounts';

const TIMELOCK = '0x36444f653E7746d69aD5d91dA920f5Cd2F9C6E83';
const REGISTRY = '0x9914436E5245bF3c0d4D4338e0a8b8F5Ab5505aB';
const BATCH_ID = '0x31218725d7f61c128825c982ecd962183136a0b755381d128052a09c84c23587';

const EXECUTE_BATCH_CALLDATA = '';

// token -> expected aggregator after migration
const EXPECT = [
  ['USDC',  '0x3BFa09fF6467639f0981948385bA1018Ac07d22C', '0x6c6519cb0c66c2269505833382f23d4e8f915480'],
  ['USDT',  '0x342B6e4fD6896f0BCc80f8e9799e2bce65b9844B', '0x3e58dd7fd2729a27961ffb11d37bff42874caa34'],
  ['PYUSD', '0xfdB2c86d010698401f0b969348DC58b6659B96a3', '0x78cb5f03b420f0cd2e8adcb141069f31a38e07e8'],
  ['DAI',   '0xFf7d46fe2f672BB6dc1586613303c7b012aCafFE', '0x3e542b4d2edbfc965028eb85140bcfea6868a37e'],
  ['EURC',  '0xe08EF7Cb507706D8ff287A41Cf607Fb2d03473BD', '0x1357cf421a8c3b732a882e4812afba6209ebebbc'],
  ['TRYC',  '0xD564EBcCFAE91f2E234b3074B0ad75eF7A820e61', '0xfe3fe7f2b2693d676e4831283dd1b81665ac9faa'],
  ['BRLC',  '0xa13c0935A98e2c175b31A4054f698819271a8FfC', '0xf5021349e0d6e2acb00beb105d7793202ac3aa46'],
];

const timelockAbi = [
  { type: 'function', name: 'isOperationReady', stateMutability: 'view',
    inputs: [{ type: 'bytes32' }], outputs: [{ type: 'bool' }] },
  { type: 'function', name: 'isOperationDone', stateMutability: 'view',
    inputs: [{ type: 'bytes32' }], outputs: [{ type: 'bool' }] },
];
const registryAbi = [
  { type: 'function', name: 'tokenInfo', stateMutability: 'view',
    inputs: [{ type: 'address' }],
    outputs: [{ type: 'tuple', components: [
      { name: 'decimals', type: 'uint8' },
      { name: 'isActive', type: 'bool' },
      { name: 'usdOracle', type: 'address' },
      { name: 'maxOracleDeviationBps', type: 'uint16' },
      { name: 'maxStaleSeconds', type: 'uint32' },
    ] }] },
];

function fail(msg) { console.error('[p3-execute] FAIL:', msg); process.exit(1); }
const log = (...a) => console.log('[p3-execute]', ...a);

async function main() {
  const rpc = process.env.RPC_URL;
  let pk = process.env.DEPLOYER_PRIVATE_KEY;
  if (!rpc) fail('RPC_URL not set');
  if (!pk) fail('DEPLOYER_PRIVATE_KEY not set');
  if (!pk.startsWith('0x')) pk = '0x' + pk;

  const arc = defineChain({
    id: 5042002,
    name: 'Arc Testnet',
    nativeCurrency: { name: 'ARC', symbol: 'ARC', decimals: 18 },
    rpcUrls: { default: { http: [rpc] } },
  });
  const account = privateKeyToAccount(pk);
  const pub = createPublicClient({ chain: arc, transport: http(rpc) });
  const wallet = createWalletClient({ account, chain: arc, transport: http(rpc) });

  log('executor:', account.address);
  log('batch id:', BATCH_ID);

  // Pre-check: the 48h Timelock delay must have elapsed.
  const ready = await pub.readContract({
    address: TIMELOCK, abi: timelockAbi, functionName: 'isOperationReady', args: [BATCH_ID] });
  if (!ready) {
    const done = await pub.readContract({
      address: TIMELOCK, abi: timelockAbi, functionName: 'isOperationDone', args: [BATCH_ID] });
    if (done) { log('batch already executed (isOperationDone=true) — nothing to do.'); return; }
    fail('batch not ready — the 48h Timelock delay has not elapsed (or the batch was never scheduled).');
  }
  log('batch is ready — sending executeBatch...');

  const hash = await wallet.sendTransaction({ to: TIMELOCK, data: EXECUTE_BATCH_CALLDATA });
  log('executeBatch tx:', hash);
  const receipt = await pub.waitForTransactionReceipt({ hash, timeout: 300_000 });
  if (receipt.status !== 'success') fail('executeBatch tx reverted: ' + hash);
  log('executeBatch mined OK, block', receipt.blockNumber.toString());

  const done = await pub.readContract({
    address: TIMELOCK, abi: timelockAbi, functionName: 'isOperationDone', args: [BATCH_ID] });
  if (!done) fail('batch not marked done after execute');

  // Verify Registry now points each token at its aggregator.
  let bad = 0;
  for (const [sym, token, expectAgg] of EXPECT) {
    const info = await pub.readContract({
      address: REGISTRY, abi: registryAbi, functionName: 'tokenInfo', args: [token] });
    const oracle = info.usdOracle.toLowerCase();
    const cap = Number(info.maxOracleDeviationBps);
    const oracleOk = oracle === expectAgg.toLowerCase();
    let capOk = true;
    if (sym === 'TRYC' || sym === 'BRLC') capOk = cap === 200;
    log(`${sym}: oracle=${oracle} ${oracleOk ? 'OK' : 'MISMATCH'}  devBps=${cap} ${capOk ? 'OK' : 'EXPECTED 200'}`);
    if (!oracleOk || !capOk) bad++;
  }
  if (bad) fail(`${bad} token(s) failed post-migration verification`);
  log('SUCCESS — Registry migrated to aggregators; TRYC/BRLC caps tightened to 200 bps.');
}

main().catch((e) => fail(e.stack || e.message || String(e)));
